CREATE TABLE [dbo].[ccriachats](	  [chatId] INT NOT NULL IDENTITY(1,1)	, [inboundId] SMALLINT NOT NULL	, [domain] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [userId] SMALLINT NOT NULL DEFAULT((0))	, [session] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [chatStatus] SMALLINT NOT NULL DEFAULT((0))	, [tChatting] SMALLINT NOT NULL DEFAULT((0))	, [tWrapUp] SMALLINT NOT NULL DEFAULT((0))	, [requestDate] DATETIME NOT NULL	, [finishedBy] TINYINT NULL	, [onQueue] BIT NULL	, [tQueue] SMALLINT NOT NULL DEFAULT((0))	, [tTimeout] INT NOT NULL DEFAULT((0))	, [disposition] SMALLINT NOT NULL DEFAULT((0))	, [subDisposition] SMALLINT NOT NULL DEFAULT((0))	, [chatDate] DATETIME NULL	, [clientName] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NULL DEFAULT('')	, [firstMessageTime] DATETIME NULL	, CONSTRAINT [PK_ccRIAChats_1] PRIMARY KEY ([chatId] ASC))CREATE NONCLUSTERED INDEX [IX_ccriachats] ON [dbo].[ccriachats] ([chatDate] ASC)